"""Те же BDF2 и BoundedState<3,7>; только сетка 48 кГц. P7 не меняется."""
from pathlib import Path
import hashlib,json
R=Path(__file__).resolve().parents[1];O=R/'simulation/experiments/rate48';O.mkdir(exist_ok=True)
s=(R/'simulation/generate_condensed.py').read_text().replace('generated_condensed.rs','generated_condensed48.rs').replace('architecture_decision/coefficients.json','rate48/coefficients.json')
g={'__name__':'rate48_generation'};exec(compile(s,'generate_condensed48','exec'),g);g['generate'](48000,'bdf2')
s=(R/'simulation/generate_packed.py').read_text().replace('sample_rate=96000','sample_rate=48000').replace('generated_condensed','generated_condensed48').replace('generated_packed.rs','generated_packed48.rs')
exec(compile(s,'generate_packed48','exec'),{'__name__':'rate48_generation'})
p=R/'firmware/orange-dsp/src/bounded.rs';body=p.read_text().split('#[cfg(test)]\n#[path="bounded_diagnostics.rs"]')[0]
s=body.replace('generated_condensed','generated_condensed48').replace('generated_packed','generated_packed48')
(R/'firmware/orange-dsp/src/bounded48.rs').write_text('// Та же реализация bounded.rs; generated by simulation/generate_rate48.py.\n'+s)
(O/'same_solver.json').write_text(json.dumps({'source_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'changes':'Only generated coefficient module names and exclusion of the old 96k diagnostic test module. No solver algorithm, tolerances, iteration caps or physics changed.','rate':48000},indent=2)+'\n')
p=R/'firmware/orange-dsp/src/lib.rs';s=p.read_text();tag='mod generated_condensed48;\nmod generated_packed48;\npub mod bounded48;\n'
if tag not in s:p.write_text(s+'\n'+tag)
